{"implementation": "def solve(case):
    items = case.get('items')
    required = set(case.get('required_failure_items', []))
    unresolved = set(case.get('unresolved_without', []))
    if not isinstance(items, list) or len(items) == 0:
        raise ValueError("items must be a non-empty list")
    if not required:
        raise ValueError("required_failure_items must be non-empty")
    for r in required:
        if r not in items:
            raise ValueError(f"required item {r!r} not in items")
    for u in unresolved:
        if u not in items:
            raise ValueError(f"unresolved_without item {u!r} not in items")

    def test(subset_indices):
        subset_items = {items[i] for i in subset_indices}
        if unresolved and not unresolvable.issubset(subset_items):
            return "UNRESOLVED"
        if required.issubset(subset_items):
            return "FAIL"
        return "PASS"

    full_indices = list(range(len(items)))
    if test(full_indices) != "FAIL":
        raise ValueError("initial configuration must produce FAIL")

    current = full_indices[:]
    test_count = 1
    granularity = 2

    while granularity <= len(current):
        n = len(current)
        chunk_size = (n + granularity - 1) // granularity
        chunks = []
        for i in range(0, n, chunk_size):
            chunks.append(current[i:i+chunk_size])
        found = False
        for chunk in chunks:
            # test subset (chunk)
            result = test(chunk)
            test_count += 1
            if result == "FAIL":
                current = chunk[:]
                granularity = 2
                found = True
                break
            # test complement
            complement = [idx for idx in current if idx not in chunk]
            if not complement:
                continue
            result = test(complement)
            test_count += 1
            if result == "FAIL":
                current = complement[:]
                granularity = 2
                found = True
                break
        if found:
            continue
        granularity *= 2

    result_items = [items[i] for i in current]
    return {
        "one_minimal_result": result_items,
        "test_count": test_count,
        "terminal_outcome": "FAIL"
    }"}
